// array[1:3] = [...], string[0] = "x" and string[1:3] = "xx"
func evalIndexAssignment(iex *ast.IndexExpression, expr object.Object, env *object.Environment) object.Object {
\tleftObj := Eval(iex.Left, env)
\tif isError(leftObj) {
\t\treturn leftObj
\t}
\tindex := Eval(iex.Index, env)
\tif isError(index) {
\t\treturn index
\t}
\tend := Eval(iex.End, env)
\tif isError(end) {
\t\treturn end
\t}
\tstep := Eval(iex.Step, env)
\tif isError(step) {
\t\treturn step
\t}

\tif leftObj.Type() == object.ARRAY_OBJ {
\t\tif iex.IsRange {
\t\t\treturn evalArrayRangeAssignment(iex.Token, leftObj.(*object.Array), index, end, step, expr, iex.StartSet, iex.End != nil, iex.Step != nil)
\t\t}
\t\tif index.Type() != object.NUMBER_OBJ {
\t\t\treturn newError(iex.Token, "index operator not supported: %s on %s", index.Inspect(), leftObj.Type())
\t\t}
\t\tarrayObject := leftObj.(*object.Array)
\t\tidx := index.(*object.Number).Int()
\t\telems := arrayObject.Elements
\t\tif idx < 0 {
\t\t\treturn newError(iex.Token, "index out of range: %d", idx)
\t\t}
\t\tif idx >= len(elems) {
\t\t\t// expand the array by appending Null objects
\t\t\tfor i := len(elems); i <= idx; i++ {
\t\t\t\telems = append(elems, NULL)
\t\t\t}
\t\t\tarrayObject.Elements = elems
\t\t}
\t\telems[idx] = expr
\t\treturn NULL
\t}
\tif leftObj.Type() == object.HASH_OBJ {
\t\thashObject := leftObj.(*object.Hash)
\t\tkey, ok := index.(object.Hashable)
\t\tif !ok {
\t\t\treturn newError(iex.Token, "unusable as hash key: %s", index.Type())
\t\t}
\t\thashed := key.HashKey()
\t\tpair := object.HashPair{Key: index, Value: expr}
\t\thashObject.Pairs[hashed] = pair
\t\treturn NULL
\t}
\tif leftObj.Type() == object.STRING_OBJ {
\t\tif iex.IsRange {
\t\t\treturn evalStringRangeAssignment(iex.Token, leftObj.(*object.String), index, end, step, expr, iex.StartSet, iex.End != nil, iex.Step != nil)
\t\t}
\t\treturn evalStringIndexAssignment(iex.Token, leftObj.(*object.String), index, expr)
\t}
\treturn NULL
}

func evalArrayRangeAssignment(tok token.Token, arrayObject *object.Array, index, end, step, expr object.Object, startSet, endSet, hasStep bool) object.Object {
\tindices, err := computeSliceIndices(tok, len(arrayObject.Elements), index, end, step, startSet, endSet, hasStep)
\tif err != nil {
\t\treturn err
\t}

\tif valueArray, ok := expr.(*object.Array); ok {
\t\tif len(valueArray.Elements) != len(indices) {
\t\t\treturn newError(tok, "range assignment size mismatch: target=%d value=%d", len(indices), len(valueArray.Elements))
\t\t}
\t\tfor pos, i := range indices {
\t\t\tarrayObject.Elements[i] = valueArray.Elements[pos]
\t\t}
\t} else {
\t\t// broadcast the value across all selected indexes
\t\tfor _, i := range indices {
\t\t\tarrayObject.Elements[i] = expr
\t\t}
\t}

\treturn NULL
}

func evalStringRangeAssignment(tok token.Token, stringObject *object.String, index, end, step, expr object.Object, startSet, endSet, hasStep bool) object.Object {
\tif expr.Type() != object.STRING_OBJ {
\t\treturn newError(tok, "range assignment expects STRING value, got %s", expr.Type())
\t}

\trunes := []rune(stringObject.Value)
\tindices, err := computeSliceIndices(tok, len(runes), index, end, step, startSet, endSet, hasStep)
\tif err != nil {
\t\treturn err
\t}

\tvalueRunes := []rune(expr.(*object.String).Value)

\tif len(indices) == 0 {
\t\tif len(valueRunes) > 0 {
\t\t\treturn newError(tok, "range assignment size mismatch: target=%d value=%d", 0, len(valueRunes))
\t\t}
\t\treturn NULL
\t}

\tif len(valueRunes) == 1 {
\t\t// broadcast a one-character string across all selected indexes
\t\tfor _, i := range indices {
\t\t\trunes[i] = valueRunes[0]
\t\t}
\t} else if len(valueRunes) == len(indices) {
\t\tfor pos, i := range indices {
\t\t\trunes[i] = valueRunes[pos]
\t\t}
\t} else {
\t\treturn newError(tok, "range assignment size mismatch: target=%d value=%d", len(indices), len(valueRunes))
\t}

\tstringObject.Value = string(runes)
\treturn NULL
}

func evalStringIndexAssignment(tok token.Token, stringObject *object.String, index, expr object.Object) object.Object {
\tif index.Type() != object.NUMBER_OBJ {
\t\treturn newError(tok, "index operator not supported: %s on %s", index.Inspect(), object.STRING_OBJ)
\t}
\tif expr.Type() != object.STRING_OBJ {
\t\treturn newError(tok, "index assignment expects STRING value, got %s", expr.Type())
	}

\tvalueRunes := []rune(expr.(*object.String).Value)
\tif len(valueRunes) != 1 {
\t\treturn newError(tok, "index assignment expects single-character STRING value, got %d characters", len(valueRunes))
\t}

\trunes := []rune(stringObject.Value)
\tidx := index.(*object.Number).Int()
\tif idx < 0 || idx >= len(runes) {
\t\treturn newError(tok, "index out of range: %d", idx)
\t}

\trunes[idx] = valueRunes[0]
\tstringObject.Value = string(runes)
\treturn NULL
}

